<?php
require __DIR__.'/config.php';$me=require_auth();$s=db()->prepare("SELECT a.account_id,a.account_number,a.account_title,a.balance,a.currency,a.status,a.opening_date,t.type_name,b.branch_name,h.holder_role FROM account_holders h JOIN accounts a ON a.account_id=h.account_id JOIN account_types t ON t.account_type_id=a.account_type_id JOIN branches b ON b.branch_id=a.branch_id WHERE h.customer_id=? ORDER BY h.holder_role='primary' DESC,a.account_id DESC");$s->execute([$me['customer_id']]);$accounts=$s->fetchAll();render_start('My accounts');?><section class="page-heading"><div class="eyebrow dark">Your money, in view</div><h1>My accounts</h1><p>Accounts where you are a primary or joint holder.</p></section><?php if($accounts):?><div class="account-grid"><?php foreach($accounts as $a):?><article class="account-card"><div class="account-top"><span class="eyebrow dark"><?=e($a['type_name'])?></span><span class="badge"><?=e(ucfirst($a['status']))?></span></div><h2><?=e($a['account_title'])?></h2><p class="account-number"><?=e($a['account_number'])?></p><strong class="balance"><?=e($a['currency'])?> <?=e(number_format((float)$a['balance'],2))?></strong><p class="muted"><?=e(ucfirst($a['holder_role']))?> holder · <?=e($a['branch_name'])?></p><a href="<?=e(url('account.php?id='.(int)$a['account_id']))?>">View account details →</a></article><?php endforeach;?></div><?php else:?><div class="empty">No accounts are linked to your profile.</div><?php endif;?><?php render_end();?>
